* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  color: white;
}

.App {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.app-header {
  text-align: center;
  padding: 2rem;
  background: rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(10px);
}

.app-header h1 {
  font-size: 3rem;
  margin-bottom: 0.5rem;
  font-weight: 700;
}

.app-header p {
  font-size: 1.2rem;
  opacity: 0.9;
}

.main-content {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

.connect-section {
  text-align: center;
}

.connect-btn {
  background: linear-gradient(45deg, #ff6b6b, #ee5a24);
  color: white;
  border: none;
  padding: 1rem 2rem;
  font-size: 1.2rem;
  border-radius: 50px;
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;
  font-weight: 600;
}

.connect-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.3);
}

.game-section {
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(15px);
  border-radius: 20px;
  padding: 2rem;
  max-width: 500px;
  width: 100%;
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.wallet-info {
  text-align: center;
  margin-bottom: 2rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.2);
}

.wallet-info p {
  margin-bottom: 0.5rem;
  font-weight: 500;
}

.game-controls {
  text-align: center;
}

.game-controls h2 {
  margin-bottom: 1.5rem;
  font-size: 1.5rem;
}

.prediction-buttons {
  display: flex;
  gap: 1rem;
  margin-bottom: 2rem;
  justify-content: center;
}

.pred-btn {
  background: rgba(255, 255, 255, 0.2);
  color: white;
  border: 2px solid rgba(255, 255, 255, 0.3);
  padding: 1rem 1.5rem;
  border-radius: 15px;
  cursor: pointer;
  transition: all 0.2s;
  font-size: 1.1rem;
  font-weight: 600;
  min-width: 120px;
}

.pred-btn:hover {
  background: rgba(255, 255, 255, 0.3);
  transform: translateY(-2px);
}

.pred-btn.active {
  background: rgba(255, 255, 255, 0.4);
  border-color: #fff;
  box-shadow: 0 0 20px rgba(255, 255, 255, 0.3);
}

.pred-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.flip-btn {
  background: linear-gradient(45deg, #2ed573, #1e90ff);
  color: white;
  border: none;
  padding: 1.2rem 3rem;
  font-size: 1.3rem;
  border-radius: 50px;
  cursor: pointer;
  transition: all 0.2s;
  font-weight: 700;
  margin-top: 1rem;
}

.flip-btn:hover:not(:disabled) {
  transform: translateY(-3px);
  box-shadow: 0 15px 30px rgba(0, 0, 0, 0.3);
}

.flip-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.warning {
  color: #ffa726;
  margin-top: 1rem;
  font-weight: 500;
}

.result {
  margin-top: 2rem;
  padding: 1.5rem;
  border-radius: 15px;
  text-align: center;
  font-weight: 600;
}

.result.win {
  background: rgba(46, 213, 115, 0.2);
  border: 2px solid #2ed573;
}

.result.lose {
  background: rgba(255, 107, 107, 0.2);
  border: 2px solid #ff6b6b;
}

.result h3 {
  margin-bottom: 0.5rem;
  font-size: 1.5rem;
}

.recent-flips {
  margin-top: 2rem;
  padding-top: 1rem;
  border-top: 1px solid rgba(255, 255, 255, 0.2);
}

.recent-flips h3 {
  text-align: center;
  margin-bottom: 1rem;
  font-size: 1.2rem;
}

.flips-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  max-height: 200px;
  overflow-y: auto;
}

.flip-item {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.8rem;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.1);
  font-size: 0.9rem;
}

.flip-item.win {
  border-left: 3px solid #2ed573;
}

.flip-item.lose {
  border-left: 3px solid #ff6b6b;
}

footer {
  text-align: center;
  padding: 1rem;
  background: rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(10px);
  opacity: 0.8;
}

/* Responsive */
@media (max-width: 768px) {
  .app-header h1 {
    font-size: 2rem;
  }

  .prediction-buttons {
    flex-direction: column;
    align-items: center;
  }

  .pred-btn {
    width: 200px;
  }

  .game-section {
    margin: 1rem;
    padding: 1.5rem;
  }
}

/* Animation for flipping */
@keyframes flip {
  0% { transform: rotateY(0deg); }
  50% { transform: rotateY(90deg); }
  100% { transform: rotateY(0deg); }
}

.flip-btn:active:not(:disabled) {
  animation: flip 0.6s ease-in-out;
}

