import { ethers } from 'ethers'
import './App.css'

const COIN_FLIP_ABI = [
  "function flip(uint8 _prediction) external payable",
  "function getStats(address player) external view returns (uint256 winCount, uint256 lossCount)",
  "event FlipRequested(uint64 indexed sequenceNumber, address indexed player, uint8 prediction)",
  "event FlipResult(uint64 indexed sequenceNumber, address indexed player, uint8 prediction, uint8 result, bool won)"
]

// This will be updated after deployment
const CONTRACT_ADDRESS = "0x0000000000000000000000000000000000000000" // TODO: Update after deployment

function App() {
  const [account, setAccount] = useState('')
  const [provider, setProvider] = useState(null)
  const [contract, setContract] = useState(null)
  const [prediction, setPrediction] = useState(0) // 0 = heads, 1 = tails
  const [isFlipping, setIsFlipping] = useState(false)
  const [stats, setStats] = useState({ wins: 0, losses: 0 })
  const [recentFlips, setRecentFlips] = useState([])
  const [flipResult, setFlipResult] = useState(null)

  useEffect(() => {
    initializeEthers()
  }, [])

  useEffect(() => {
    if (contract && account) {
      loadStats()
      setupEventListeners()
    }
  }, [contract, account])

  const initializeEthers = async () => {
    if (typeof window.ethereum !== 'undefined') {
      try {
        const provider = new ethers.BrowserProvider(window.ethereum)
        setProvider(provider)

        const accounts = await window.ethereum.request({ method: 'eth_accounts' })
        if (accounts.length > 0) {
          setAccount(accounts[0])
          const signer = await provider.getSigner()
          const contract = new ethers.Contract(CONTRACT_ADDRESS, COIN_FLIP_ABI, signer)
          setContract(contract)
        }
      } catch (error) {
        console.error('Failed to initialize ethers:', error)
      }
    }
  }

  const connectWallet = async () => {
    if (typeof window.ethereum !== 'undefined') {
      try {
        await window.ethereum.request({ method: 'eth_requestAccounts' })
        const provider = new ethers.BrowserProvider(window.ethereum)
        const signer = await provider.getSigner()
        const address = await signer.getAddress()

        setAccount(address)
        setProvider(provider)

        const contract = new ethers.Contract(CONTRACT_ADDRESS, COIN_FLIP_ABI, signer)
        setContract(contract)
      } catch (error) {
        console.error('Failed to connect wallet:', error)
      }
    } else {
      alert('Please install MetaMask to play!')
    }
  }

  const loadStats = async () => {
    if (contract && account) {
      try {
        const [wins, losses] = await contract.getStats(account)
        setStats({ wins: Number(wins), losses: Number(losses) })
      } catch (error) {
        console.error('Failed to load stats:', error)
      }
    }
  }

  const setupEventListeners = () => {
    if (contract) {
      // Listen for flip results
      contract.on('FlipResult', (sequenceNumber, player, prediction, result, won, event) => {
        if (player.toLowerCase() === account.toLowerCase()) {
          const resultData = {
            sequenceNumber: sequenceNumber.toString(),
            prediction: Number(prediction),
            result: Number(result),
            won: won,
            timestamp: Date.now()
          }

          setFlipResult(resultData)
          setRecentFlips(prev => [resultData, ...prev.slice(0, 9)]) // Keep last 10
          setIsFlipping(false)
          loadStats() // Refresh stats
        }
      })
    }
  }

  const flipCoin = async () => {
    if (!contract) return

    setIsFlipping(true)
    setFlipResult(null)

    try {
      // Get the fee for randomness (usually around 0.001 ETH)
      const fee = ethers.parseEther('0.001')
      const tx = await contract.flip(prediction, { value: fee })
      await tx.wait()
    } catch (error) {
      console.error('Failed to flip coin:', error)
      setIsFlipping(false)
      alert('Failed to flip coin. Make sure you have enough ETH for the transaction fee.')
    }
  }

  const formatAddress = (addr) => {
    return `${addr.slice(0, 6)}...${addr.slice(-4)}`
  }

  return (
    <div className="App">
      <header className="app-header">
        <h1>🪙 TESTOTA - Coin Flip</h1>
        <p>Provably fair coin flips powered by Pyth Entropy</p>
      </header>

      <main className="main-content">
        {!account ? (
          <div className="connect-section">
            <button onClick={connectWallet} className="connect-btn">
              Connect Wallet
            </button>
            <p>Connect your wallet to start flipping coins!</p>
          </div>
        ) : (
          <div className="game-section">
            <div className="wallet-info">
              <p>Connected: {formatAddress(account)}</p>
              <p>Wins: {stats.wins} | Losses: {stats.losses}</p>
            </div>

            <div className="game-controls">
              <h2>Make Your Prediction</h2>
              <div className="prediction-buttons">
                <button 
                  className={`pred-btn ${prediction === 0 ? 'active' : ''}`}
                  onClick={() => setPrediction(0)}
                  disabled={isFlipping}
                >
                  🟡 Heads
                </button>
                <button 
                  className={`pred-btn ${prediction === 1 ? 'active' : ''}`}
                  onClick={() => setPrediction(1)}
                  disabled={isFlipping}
                >
                  ⚪ Tails
                </button>
              </div>

              <button 
                onClick={flipCoin} 
                disabled={isFlipping || CONTRACT_ADDRESS === "0x0000000000000000000000000000000000000000"}
                className="flip-btn"
              >
                {isFlipping ? 'Flipping...' : 'Flip Coin!'}
              </button>

              {CONTRACT_ADDRESS === "0x0000000000000000000000000000000000000000" && (
                <p className="warning">⚠️ Contract not deployed yet - coming soon!</p>
              )}
            </div>

            {flipResult && (
              <div className={`result ${flipResult.won ? 'win' : 'lose'}`}>
                <h3>{flipResult.won ? '🎉 You Won!' : '💔 You Lost!'}</h3>
                <p>
                  You predicted: {flipResult.prediction === 0 ? 'Heads' : 'Tails'} | 
                  Result: {flipResult.result === 0 ? 'Heads' : 'Tails'}
                </p>
              </div>
            )}

            {recentFlips.length > 0 && (
              <div className="recent-flips">
                <h3>Recent Flips</h3>
                <div className="flips-list">
                  {recentFlips.map((flip, index) => (
                    <div key={flip.sequenceNumber} className={`flip-item ${flip.won ? 'win' : 'lose'}`}>
                      <span>{flip.won ? '✅' : '❌'}</span>
                      <span>{flip.prediction === 0 ? 'Heads' : 'Tails'} → {flip.result === 0 ? 'Heads' : 'Tails'}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </main>

      <footer>
        <p>Built with Pyth Network | Base Sepolia</p>
      </footer>
    </div>
  )
}

export default App"}

