{"path": "src/CoinFlip.sol", "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "../lib/pyth-crosschain/target_chains/ethereum/contracts/pyth/IEntropy.sol";
import "../lib/pyth-crosschain/target_chains/ethereum/contracts/pyth/IEntropyConsumer.sol";

contract CoinFlip is IEntropyConsumer {
    IEntropy entropy;

    struct FlipRequest {
        address player;
        uint8 prediction; // 0 = heads, 1 = tails
        bool resolved;
        bool won;
    }

    mapping(uint64 => FlipRequest) public flipRequests;
    mapping(address => uint256) public wins;
    mapping(address => uint256) public losses;

    event FlipRequested(uint64 indexed sequenceNumber, address indexed player, uint8 prediction);
    event FlipResult(uint64 indexed sequenceNumber, address indexed player, uint8 prediction, uint8 result, bool won);

    constructor(address _entropy) {
        entropy = IEntropy(_entropy);
    }

    function flip(uint8 _prediction) external payable {
        require(_prediction <= 1, "Invalid prediction");
        require(msg.value >= 0.001 ether, "Minimum fee required");

        // Request randomness from Pyth Entropy
        uint64 sequenceNumber = entropy.requestWithCallback{value: msg.value}(
            entropy.getDefaultProvider(),
            bytes32(0) // No user commitment needed for this simple game
        );

        flipRequests[sequenceNumber] = FlipRequest({
            player: msg.sender,
            prediction: _prediction,
            resolved: false,
            won: false
        });

        emit FlipRequested(sequenceNumber, msg.sender, _prediction);
    }

    function entropyCallback(
        uint64 sequenceNumber,
        address,
        bytes32 randomValue
    ) internal override {
        FlipRequest storage request = flipRequests[sequenceNumber];
        require(request.player != address(0), "Request not found");
        require(!request.resolved, "Request already resolved");

        // Extract coin flip result from random value
        uint8 result = uint8(randomValue) % 2;
        bool won = result == request.prediction;

        request.resolved = true;
        request.won = won;

        if (won) {
            wins[request.player]++;
        } else {
            losses[request.player]++;
        }

        emit FlipResult(sequenceNumber, request.player, request.prediction, result, won);
    }

    function getStats(address player) external view returns (uint256 winCount, uint256 lossCount) {
        return (wins[player], losses[player]);
    }

    function getEntropy() external view returns (address) {
        return address(entropy);
    }
}"}

{"path": "src/IEntropy.sol", "content": "// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.0;

interface IEntropy {
    // This method requests a random number from the entropy protocol.
    // callback is the address of the contract that will receive the random number.
    // The method returns a sequence number that can be used to identify the request.
    function requestWithCallback(
        address provider,
        bytes32 userCommitment
    ) external payable returns (uint64 sequenceNumber);

    // Get the default provider for requesting randomness
    function getDefaultProvider() external view returns (address);

    // Get the fee for requesting randomness from a provider
    function getFee(address provider) external view returns (uint128);
}"}

{"path": "src/IEntropyConsumer.sol", "content": "// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.0;

interface IEntropyConsumer {
    // This method is called by the entropy contract when randomness is available.
    function entropyCallback(
        uint64 sequenceNumber,
        address provider,
        bytes32 randomValue
    ) external;
}

// Abstract contract that implements the IEntropyConsumer interface
abstract contract EntropyConsumer is IEntropyConsumer {
    address private entropy;

    modifier onlyEntropy() {
        require(msg.sender == entropy, "Only entropy contract can call this function");
        _;
    }

    constructor(address _entropy) {
        entropy = _entropy;
    }

    function entropyCallback(
        uint64 sequenceNumber,
        address provider,
        bytes32 randomValue
    ) external override onlyEntropy {
        _entropyCallback(sequenceNumber, provider, randomValue);
    }

    // This method must be implemented by the consumer contract
    function _entropyCallback(
        uint64 sequenceNumber,
        address provider,
        bytes32 randomValue
    ) internal virtual;

    function getEntropy() public view returns (address) {
        return entropy;
    }
}"}

