pragma solidity ^0.8.0;

// Mock version for demonstration - uses pseudo-random for immediate results
contract MockCoinFlip {
    struct FlipRequest {
        address player;
        uint8 prediction;
        bool resolved;
        bool won;
        uint256 timestamp;
    }

    mapping(uint256 => FlipRequest) public flipRequests;
    mapping(address => uint256) public wins;
    mapping(address => uint256) public losses;

    uint256 public flipCounter;

    event FlipRequested(uint256 indexed flipId, address indexed player, uint8 prediction);
    event FlipResult(uint256 indexed flipId, address indexed player, uint8 prediction, uint8 result, bool won);

    function flip(uint8 _prediction) external {
        require(_prediction <= 1, "Invalid prediction");

        flipCounter++;

        // Generate pseudo-random result for demo
        uint8 result = uint8(uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, msg.sender, flipCounter))) % 2);
        bool won = result == _prediction;

        flipRequests[flipCounter] = FlipRequest({
            player: msg.sender,
            prediction: _prediction,
            resolved: true,
            won: won,
            timestamp: block.timestamp
        });

        if (won) {
            wins[msg.sender]++;
        } else {
            losses[msg.sender]++;
        }

        emit FlipRequested(flipCounter, msg.sender, _prediction);
        emit FlipResult(flipCounter, msg.sender, _prediction, result, won);
    }

    function getStats(address player) external view returns (uint256 winCount, uint256 lossCount) {
        return (wins[player], losses[player]);
    }

    function getFlipResult(uint256 flipId) external view returns (address player, uint8 prediction, uint8 result, bool won) {
        FlipRequest memory request = flipRequests[flipId];
        uint8 result = uint8(uint256(keccak256(abi.encodePacked(request.timestamp, request.player, flipId))) % 2);
        return (request.player, request.prediction, result, request.won);
    }
}"}

