  cursor: not-allowed;
  transform: none;
}

.warning {
  color: #ffa726;
  margin-top: 1rem;
  font-weight: 500;
}

.result {
  margin-top: 2rem;
  padding: 1.5rem;
  border-radius: 15px;
  text-align: center;
  font-weight: 600;
}

.result.win {
  background: rgba(46, 213, 115, 0.2);
  border: 2px solid #2ed573;
}

.result.lose {
  background: rgba(255, 107, 107, 0.2);
  border: 2px solid #ff6b6b;
}

.result h3 {
  margin-bottom: 0.5rem;
  font-size: 1.5rem;
}

.recent-flips {
  margin-top: 2rem;
  padding-top: 1rem;
  border-top: 1px solid rgba(255, 255, 255, 0.2);
}

.recent-flips h3 {
  text-align: center;
  margin-bottom: 1rem;
  font-size: 1.2rem;
}

.flips-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  max-height: 200px;
  overflow-y: auto;
}

.flip-item {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.8rem;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.1);
  font-size: 0.9rem;
}

.flip-item.win {
  border-left: 3px solid #2ed573;
}

.flip-item.lose {
  border-left: 3px solid #ff6b6b;
}

footer {
  text-align: center;
  padding: 1rem;
  background: rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(10px);
  opacity: 0.8;
}

/* Responsive */
@media (max-width: 768px) {
  .app-header h1 {
    font-size: 2rem;
  }

  .prediction-buttons {
    flex-direction: column;
    align-items: center;
  }

  .pred-btn {
    width: 200px;
  }

  .game-section {
    margin: 1rem;
    padding: 1.5rem;
  }
}

/* Animation for flipping */
@keyframes flip {
  0% { transform: rotateY(0deg); }
  50% { transform: rotateY(90deg); }
  100% { transform: rotateY(0deg); }
}

.flip-btn:active:not(:disabled) {
  animation: flip 0.6s ease-in-out;
}"}

